import type { ComponentProps, ElementType, MouseEvent, ReactNode } from "react";

import { Badge } from "@rhs-ui/primitives/badge";
import { DropdownMenuItem } from "@rhs-ui/primitives/dropdown-menu";
import { PriorityNavRow, type PriorityNavEntry } from "@rhs-ui/primitives/priority-nav/overflow";
import { cn } from "@/lib/utils";

export interface PriorityNavItem {
  /** The text of the link. */
  label: string;
  /** Where the link goes. */
  href: string;
  /** A number after the label: open issues, unread items. It stays with the link in the row and in the menu. */
  count?: number;
  /** An icon element ahead of the label: `<IconBook />`. */
  icon?: ReactNode;
}

export interface PriorityNavLabels {
  /** The count in the name of the menu button, for one link; `{count}` is the number. Default "{count} link". */
  one?: string;
  /** The same for any other number of links. Default "{count} links". */
  other?: string;
}

export interface PriorityNavProps extends Omit<ComponentProps<"nav">, "children"> {
  /** The links, in the order they should read in the row and in the menu. */
  items: readonly PriorityNavItem[];
  /** The address of the page being shown. Its link gets aria-current="page" and is never moved into the menu. A page below a link's address (/issues/42) belongs to the longest link that contains it. */
  currentHref?: string;
  /** The text of the menu button, followed in its name by how many links it holds: "More, 3 links". Default "More". */
  moreLabel?: string;
  /** Called with the address of a link chosen with a plain click, in the row or the menu; the browser's own navigation is then skipped, so route yourself. A function, so use it from a Client Component. */
  onNavigate?: (href: string) => void;
  /** Renders the links. Defaults to "a"; pass your router's Link. */
  linkAs?: ElementType;
  /** `line` underlines the current page, on a hairline; `pill` fills it. Default "line". */
  variant?: "line" | "pill";
  /** The locale the counts are written in. Default "en-US". */
  locale?: string;
  /** Words for the name of the menu button, for another language. */
  labels?: PriorityNavLabels;
}

/** A page below a link belongs to it ("/repo/issues/42" is in "/repo/issues"); the longest link that contains it wins, so "/repo" never claims "/repo/issues/42". */
function currentIndexOf(items: readonly PriorityNavItem[], currentHref: string | undefined): number {
  if (currentHref === undefined) return -1;
  const pathOf = (href: string) => href.split(/[?#]/, 1)[0] ?? "";
  const path = pathOf(currentHref);
  const exact = items.findIndex((item) => pathOf(item.href) === path);
  if (exact !== -1) return exact;
  let best = -1;
  let length = 0;
  items.forEach((item, index) => {
    const base = pathOf(item.href).replace(/\/+$/, "");
    if (base !== "" && path.startsWith(`${base}/`) && base.length > length) {
      best = index;
      length = base.length;
    }
  });
  return best;
}

/** Every link is medium weight, current or not, so choosing one never changes any width. */
const LINK =
  "group/link relative inline-flex shrink-0 items-center gap-2 font-medium whitespace-nowrap text-muted-foreground outline-none select-none transition-colors duration-150 hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-inset focus-visible:ring-ring/40 aria-[current=page]:text-foreground motion-reduce:transition-none [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4";

const VARIANT = {
  line: "h-10 rounded-md px-3 text-sm after:pointer-events-none after:absolute after:inset-x-3 after:bottom-0 after:h-0.5 after:rounded-full after:bg-foreground after:opacity-0 after:transition-opacity after:duration-150 hover:after:opacity-20 aria-[current=page]:after:opacity-100 motion-reduce:after:transition-none",
  pill: "h-8 rounded-full px-3 text-[0.8125rem] hover:bg-muted/70 aria-[current=page]:bg-muted data-[state=open]:bg-muted/70",
} as const;

/**
 * A row of section links (Overview, Issues, Pull requests, Settings) that never wraps and never scrolls: it shows
 * as many links as fit and moves the rest into a More menu, in the same order. Unlike a plain overflow row it keeps
 * the current page in view: when that page would fall into the menu it takes the place of the last link that
 * fits, and that one moves in its place. Every link exists once in the accessibility tree, aria-current marks the
 * page, a count stays with its link, and the menu button is named after how many links it holds. It measures its
 * own width, so it works in a header, a card or a sidebar. With `linkAs` it is rendered by a Server Component.
 */
export function PriorityNav({
  items,
  currentHref,
  moreLabel = "More",
  onNavigate,
  linkAs: Link = "a",
  variant = "line",
  locale = "en-US",
  labels,
  className,
  "aria-label": ariaLabel = "Section",
  ...props
}: PriorityNavProps) {
  const numbers = new Intl.NumberFormat(locale);
  const at = currentIndexOf(items, currentHref);
  const linkClass = cn(LINK, VARIANT[variant]);

  const entries: PriorityNavEntry[] = items.map((item, index) => {
    const current = index === at;
    const count = item.count === undefined ? null : numbers.format(item.count);
    const press = onNavigate
      ? (event: MouseEvent<HTMLElement>) => {
          // A modified click opens the address the way the browser does; only a plain one is yours.
          if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
          event.preventDefault();
          onNavigate(item.href);
        }
      : undefined;
    const countBadge =
      count === null ? null : (
        <Badge variant="muted" className="h-[1.125rem] min-w-[1.125rem] px-1.5 text-[0.6875rem] tabular-nums transition-colors duration-150 group-aria-[current=page]/link:bg-foreground/10 group-aria-[current=page]/link:text-foreground motion-reduce:transition-none">
          <span className="sr-only">, </span>
          {count}
        </Badge>
      );
    const inside = (
      <>
        {item.icon}
        <span className="min-w-0 truncate">{item.label}</span>
        {countBadge}
      </>
    );
    return {
      id: String(index),
      current,
      link: (
        <Link href={item.href} aria-current={current ? "page" : undefined} onClick={press} className={linkClass}>
          {inside}
        </Link>
      ),
      // The same box, without an address: measuring it can neither navigate nor prefetch anything.
      probe: <span className={linkClass}>{inside}</span>,
      item: (
        <DropdownMenuItem asChild>
          <Link href={item.href} aria-current={current ? "page" : undefined} onClick={press}>
            {item.icon}
            <span className="min-w-0 flex-1 truncate">{item.label}</span>
            {count === null ? null : (
              <span className="pl-4 text-xs text-muted-foreground tabular-nums">
                <span className="sr-only">, </span>
                {count}
              </span>
            )}
          </Link>
        </DropdownMenuItem>
      ),
    };
  });

  return (
    <nav data-slot="priority-nav" data-variant={variant} aria-label={ariaLabel} className={cn("relative min-w-0", variant === "line" && "border-b border-border", className)} {...props}>
      <PriorityNavRow entries={entries} moreLabel={moreLabel} one={labels?.one ?? "{count} link"} other={labels?.other ?? "{count} links"} locale={locale} moreClassName={linkClass} />
    </nav>
  );
}

"use client";

import { Fragment, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type ReactNode } from "react";

import { IconChevronDown } from "@rhs-ui/icons";
import { DropdownMenu, DropdownMenuContent, DropdownMenuTrigger } from "@rhs-ui/primitives/dropdown-menu";
import { cn } from "@/lib/utils";

/** One link of the row, drawn three ways by the server half: in the row, as a hidden twin to measure, and as a menu item. */
export interface PriorityNavEntry {
  /** A key for the link, unique among the entries. */
  id: string;
  /** The page being shown: this link is never moved into the menu. */
  current: boolean;
  /** The link as it is drawn in the row. */
  link: ReactNode;
  /** The same box without an address, hidden, so it can be measured without navigating or prefetching anything. */
  probe: ReactNode;
  /** The link as a menu item, for when it does not fit the row. */
  item: ReactNode;
}

export interface PriorityNavRowProps {
  /** Every link, in the order it should read in the row and in the menu. */
  entries: readonly PriorityNavEntry[];
  /** The text of the menu button. */
  moreLabel: string;
  /** The count in the menu button's name, for one link. `{count}` is the number. */
  one: string;
  /** The same for any other number of links. */
  other: string;
  /** The locale the number in the menu button's name is written in. */
  locale: string;
  /** The classes of a link, so the menu button looks like one. */
  moreClassName: string;
}

/** The space between links in the row, in px (gap-1). */
const GAP = 4;

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/**
 * Which links do not fit, by id. The current page is kept first; then links are added in order for as long as they
 * fit, so what stays is the start of the list plus the current page, and what moves keeps its order.
 */
function distribute(entries: readonly PriorityNavEntry[], widths: ReadonlyMap<string, number>, available: number, moreWidth: number): string[] {
  const ids = entries.map((entry) => entry.id);
  const total = (list: readonly string[]) => list.reduce((sum, id) => sum + (widths.get(id) ?? 0), 0) + GAP * Math.max(0, list.length - 1);
  // A hidden or unmeasured container tells nothing: keep everything in the row.
  if (available <= 0 || total(ids) <= available + 0.5) return [];
  const room = available - moreWidth - GAP;
  const kept = new Set<string>();
  const current = entries.find((entry) => entry.current);
  if (current) kept.add(current.id);
  for (const entry of entries) {
    if (kept.has(entry.id)) continue;
    if (total([...kept, entry.id]) > room) break;
    kept.add(entry.id);
  }
  return ids.filter((id) => !kept.has(id));
}

/**
 * The measuring half of Priority nav. It shows the links that fit and a More menu for the rest, and measures hidden
 * twins of every link (never the live row, so it cannot flicker). Every link exists once in the accessibility tree,
 * in the row or in the menu: the twins are hidden from it and cannot take focus.
 */
export function PriorityNavRow({ entries, moreLabel, one, other, locale, moreClassName }: PriorityNavRowProps) {
  const root = useRef<HTMLDivElement>(null);
  const probe = useRef<HTMLDivElement>(null);
  const [moved, setMoved] = useState<readonly string[]>([]);
  const [menuOpen, setMenuOpen] = useState(false);
  const numbers = useMemo(() => new Intl.NumberFormat(locale), [locale]);

  // What the measuring reads is kept in a ref, so a new `entries` array on every render does not restart the observers.
  const latest = useRef(entries);
  useEffect(() => {
    latest.current = entries;
  });
  const signature = entries.map((entry) => `${entry.id}:${entry.current ? 1 : 0}`).join("|");

  const measure = useCallback(() => {
    const host = root.current;
    const twins = probe.current;
    if (!host || !twins) return;
    const widths = new Map<string, number>();
    let moreWidth = 0;
    for (const child of Array.from(twins.children)) {
      const width = child.getBoundingClientRect().width;
      const id = (child as HTMLElement).dataset.id;
      if (id === undefined) moreWidth = width;
      else widths.set(id, width);
    }
    const next = distribute(latest.current, widths, host.clientWidth, moreWidth);
    setMoved((previous) => (previous.length === next.length && previous.every((id, index) => id === next[index]) ? previous : next));
  }, []);

  useIsoLayoutEffect(() => {
    const host = root.current;
    const twins = probe.current;
    if (!host || !twins) return;
    measure();
    // The observers answer on the next frame: a change of layout in their own callback ends in "loop completed with undelivered notifications".
    let frame = 0;
    const observer = new ResizeObserver(() => {
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(measure);
    });
    observer.observe(host);
    for (const child of Array.from(twins.children)) observer.observe(child);
    // A web font arriving changes every width.
    void document.fonts?.ready.then(() => measure());
    return () => {
      window.cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [measure, signature, moreLabel, moreClassName]);

  const inRow = entries.filter((entry) => !moved.includes(entry.id));
  const inMenu = entries.filter((entry) => moved.includes(entry.id));
  // A menu with nothing in it is gone; it must not come back already open the next time something is moved into it.
  const holdsLinks = inMenu.length > 0;
  useEffect(() => {
    if (!holdsLinks) setMenuOpen(false);
  }, [holdsLinks]);
  const countText = (inMenu.length === 1 ? one : other).replace("{count}", numbers.format(inMenu.length));
  const more = (
    <>
      {moreLabel}
      <IconChevronDown className="size-3.5 transition-transform duration-150 group-data-[state=open]/more:rotate-180 motion-reduce:transition-none" />
    </>
  );

  return (
    // With less room than the current page and the menu button need together, the current page gives way (its text is cut) before the button is. Only once there is a menu: before the first measure nothing is in it, and the row just ends at its edge.
    <div
      ref={root}
      data-overflowing={inMenu.length ? "" : undefined}
      className="relative flex min-w-0 items-center gap-1 overflow-hidden data-[overflowing]:[&>[aria-current=page]]:min-w-0 data-[overflowing]:[&>[aria-current=page]]:shrink"
    >

      {inRow.map((entry) => (
        <Fragment key={entry.id}>{entry.link}</Fragment>
      ))}

      {inMenu.length ? (
        <DropdownMenu open={menuOpen} onOpenChange={setMenuOpen}>
          <DropdownMenuTrigger asChild>
            <button type="button" aria-label={`${moreLabel}, ${countText}`} className={cn(moreClassName, "group/more cursor-pointer data-[state=open]:text-foreground")}>
              {more}
            </button>
          </DropdownMenuTrigger>
          {/* Choosing a link closes the menu here, not in the menu item: a click that is handled (your router, onNavigate) is default-prevented, and then the item never closes it. */}
          <DropdownMenuContent
            align="end"
            className="min-w-52"
            onClick={(event) => {
              if ((event.target as HTMLElement).closest("[role='menuitem']")) setMenuOpen(false);
            }}
          >
            {inMenu.map((entry) => (
              <Fragment key={entry.id}>{entry.item}</Fragment>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      ) : null}

      {/* Hidden twins, one per link and one for the menu button. They are measured and never shown, focused or read. */}
      <div aria-hidden="true" className="pointer-events-none invisible absolute top-0 left-0 h-0 w-0 overflow-hidden">
        <div ref={probe} inert className="flex w-max" style={{ gap: GAP }}>
          {entries.map((entry) => (
            <span key={entry.id} data-id={entry.id} className="flex shrink-0">
              {entry.probe}
            </span>
          ))}
          <span className={cn(moreClassName, "group/more")}>{more}</span>
        </div>
      </div>
    </div>
  );
}
